// Shared expressive Material 3 theme for every artboard. gen.mjs writes the
// exported string to ../project/theme.css. Colour roles are derived from one
// accent, so the accent Tweak re-tones everything.
const poly = (fn, n = 72) => 'polygon(' + Array.from({ length: n }, (_, i) => { const a = i / n * 2 * Math.PI; const r = fn(a); return (50 + 50 * r * Math.cos(a)).toFixed(1) + '% ' + (50 + 50 * r * Math.sin(a)).toFixed(1) + '%'; }).join(',') + ')';
const SH = {
  cookie: poly(a => 0.91 + 0.09 * Math.cos(9 * a)),
  clover: poly(a => 0.76 + 0.24 * Math.abs(Math.cos(2 * a)) ** 0.7),
  flower: poly(a => 0.84 + 0.16 * Math.cos(6 * a)),
  burst: poly(a => 0.86 + 0.14 * (2 / Math.PI) * Math.asin(Math.sin(12 * a))),
  blob: poly(a => 0.84 + 0.09 * Math.cos(3 * a) + 0.07 * Math.sin(5 * a)),
  round: poly(() => 1)
};
export const wavyRing = (r = 46, amp = 3.2, waves = 14, n = 180) => 'M' + Array.from({ length: n + 1 }, (_, i) => { const a = i / n * 2 * Math.PI; const q = r + amp * Math.sin(waves * a); return (50 + q * Math.cos(a)).toFixed(2) + ' ' + (50 + q * Math.sin(a)).toFixed(2); }).join('L') + 'Z';

export const CSS = `/* Material Asus Router: shared expressive Material 3 theme for every artboard.
   Generated by design/canvas/generator/gen.mjs from theme.mjs. Every colour
   role is derived from one accent, so the accent Tweak re-tones the whole app. */
@property --v{syntax:'<integer>';inherits:false;initial-value:0}
@property --ang{syntax:'<angle>';inherits:false;initial-value:0deg}
:root{--accent:#4f5bd5;--dark:0;--font:'Roboto Flex',system-ui,sans-serif}
.mx{
  --primary:oklch(from var(--accent) min(l,calc(0.52 + var(--dark) * 0.2)) c h);
  --on-primary:oklch(from var(--accent) calc(1 - var(--dark) * 0.82) 0.02 h);
  --link:oklch(from var(--accent) calc(0.44 + var(--dark) * 0.4) c h);
  --primary-c:oklch(from var(--accent) calc(0.92 - var(--dark) * 0.6) calc(c * 0.42) h);
  --on-primary-c:oklch(from var(--accent) calc(0.24 + var(--dark) * 0.68) calc(c * 0.9) h);
  --tertiary:oklch(from var(--accent) calc(0.5 + var(--dark) * 0.26) 0.17 calc(h + 150));
  --tertiary-c:oklch(from var(--accent) calc(0.92 - var(--dark) * 0.6) 0.075 calc(h + 150));
  --on-tertiary-c:oklch(from var(--accent) calc(0.27 + var(--dark) * 0.65) 0.1 calc(h + 150));
  --secondary:oklch(from var(--accent) calc(0.5 + var(--dark) * 0.26) 0.15 calc(h + 60));
  --secondary-c:oklch(from var(--accent) calc(0.925 - var(--dark) * 0.61) 0.06 calc(h + 60));
  --on-secondary-c:oklch(from var(--accent) calc(0.27 + var(--dark) * 0.65) 0.08 calc(h + 60));
  --f1:oklch(from var(--accent) 0.36 calc(c * 1.05) h);
  --f2:oklch(from var(--accent) 0.3 calc(c * 0.9) calc(h - 38));
  --b1:oklch(from var(--accent) 0.5 0.22 calc(h + 55));
  --b2:oklch(from var(--accent) 0.45 0.19 calc(h - 60));
  --b3:oklch(from var(--accent) 0.47 0.17 calc(h + 150));
  --bg:oklch(from var(--accent) calc(0.972 - var(--dark) * 0.835) 0.014 h);
  --surf:oklch(from var(--accent) calc(1 - var(--dark) * 0.8) 0.008 h);
  --surf-low:oklch(from var(--accent) calc(0.955 - var(--dark) * 0.78) 0.018 h);
  --surf-high:oklch(from var(--accent) calc(0.915 - var(--dark) * 0.66) 0.026 h);
  --glass:oklch(from var(--accent) calc(1 - var(--dark) * 0.78) 0.012 h / .62);
  --text:oklch(from var(--accent) calc(0.19 + var(--dark) * 0.76) 0.022 h);
  --sub:oklch(from var(--accent) calc(0.42 + var(--dark) * 0.38) 0.03 h);
  --line:oklch(from var(--accent) calc(0.87 - var(--dark) * 0.56) 0.022 h);
  --good:oklch(calc(0.5 + var(--dark) * 0.26) 0.15 152);--good-c:oklch(calc(0.93 - var(--dark) * 0.62) 0.07 152);--on-good-c:oklch(calc(0.28 + var(--dark) * 0.62) 0.09 152);
  --warn:oklch(calc(0.55 + var(--dark) * 0.25) 0.14 70);--warn-c:oklch(calc(0.94 - var(--dark) * 0.63) 0.08 78);--on-warn-c:oklch(calc(0.3 + var(--dark) * 0.62) 0.08 70);
  --bad:oklch(calc(0.52 + var(--dark) * 0.22) 0.2 25);--bad-c:oklch(calc(0.93 - var(--dark) * 0.62) 0.065 25);--on-bad-c:oklch(calc(0.3 + var(--dark) * 0.62) 0.11 25);
  --e1:0 1px 1px rgb(12 14 40 / .05),0 3px 10px rgb(12 14 40 / .05),inset 0 1px 0 rgb(255 255 255 / calc(.7 - var(--dark) * .62));
  --e2:0 2px 4px rgb(12 14 40 / .06),0 10px 24px rgb(12 14 40 / .08),0 30px 60px rgb(12 14 40 / .07),inset 0 1px 0 rgb(255 255 255 / calc(.7 - var(--dark) * .62));
  --e3:0 6px 14px rgb(12 14 40 / .14),0 26px 60px rgb(12 14 40 / .22),0 60px 120px rgb(12 14 40 / .16);
  --spring:linear(0,.18 5%,.6 13%,.93 22%,1.09 31%,1.1 38%,1.03 52%,.99 66%,1);
  --ease:cubic-bezier(.2,.8,.2,1);
  font-family:var(--font);color:var(--text);background:var(--bg);font-optical-sizing:auto;-webkit-font-smoothing:antialiased;font-size:15px;line-height:1.4
}
.mx,.mx *,.mx *::before,.mx *::after{box-sizing:border-box}
:where(.mx a){color:var(--link)}
.mx h1,.mx h2,.mx h3,.mx p{margin:0}
.mx dc-import,dc-import{display:block;min-width:0}
.mx :focus-visible{outline:3px solid var(--link);outline-offset:3px;transition:outline-offset .25s var(--spring)}
:where(.mx button){font:inherit;color:inherit;cursor:pointer;border:0;background:none;padding:0}
.mx .i{flex:none}

/* ---------- shell ---------- */
.shell{display:grid;grid-template-columns:272px minmax(0,1fr);min-height:900px;background:
  radial-gradient(900px 520px at 78% -8%,oklch(from var(--accent) calc(.86 - var(--dark) * .58) .09 calc(h + 55) / .55),transparent 70%),
  radial-gradient(700px 480px at 12% 2%,oklch(from var(--accent) calc(.88 - var(--dark) * .6) .08 calc(h - 50) / .5),transparent 70%),var(--bg)}
.railwrap{display:flex;min-width:0}
.railwrap>dc-import{flex:1}
.main{min-width:0;display:flex;flex-direction:column}
.content{overflow-x:clip;padding:8px 28px 120px;display:flex;flex-direction:column;gap:20px;min-width:0}
.rail{overflow:hidden;width:100%;height:100%;min-height:900px;padding:18px 14px 26px;display:flex;flex-direction:column;gap:2px;background:var(--glass);backdrop-filter:blur(26px) saturate(1.5);border-right:1px solid var(--line)}
.brandrow{display:flex;align-items:center;gap:12px;padding:4px 8px 16px}
.logo{width:46px;height:46px;flex:none;display:grid;place-items:center;color:#fff;background:linear-gradient(140deg,var(--b1),var(--f1));clip-path:${SH.cookie}}
.brand{font-weight:820;font-size:17px;line-height:1.05;font-stretch:112%}
.brand small{display:block;font-weight:520;font-size:12px;color:var(--sub);font-stretch:100%;margin-top:3px}
.fab{position:relative;display:flex;align-items:center;gap:12px;height:56px;padding:0 20px;border-radius:20px;background:linear-gradient(135deg,var(--f1),var(--b2));color:#fff!important;font-weight:740;font-size:15px;box-shadow:var(--e2);margin:2px 0 12px;text-decoration:none;isolation:isolate;transition:transform .35s var(--spring),border-radius .35s var(--spring)}
.fab:hover{transform:translateY(-2px) scale(1.02);border-radius:28px}
.fab:active{transform:scale(.96)}
.fab .badge{margin-left:auto;min-width:26px;height:26px;border-radius:13px;background:#fff;color:var(--f1);display:grid;place-items:center;font-size:13px;font-weight:800;padding:0 7px}
.navsec{font-size:11.5px;font-weight:760;color:var(--sub);padding:14px 14px 5px;letter-spacing:.9px;text-transform:uppercase}
.navi{display:flex;align-items:center;gap:13px;min-height:44px;padding:0 14px;border-radius:22px;color:var(--sub);font-weight:620;font-size:14.5px;text-decoration:none;position:relative;transition:background .25s,transform .35s var(--spring),color .2s}
.navi:hover{background:var(--surf-high);transform:translateX(4px);color:var(--text)}
.navi.on{background:var(--primary-c);color:var(--on-primary-c);font-weight:760;box-shadow:var(--e1)}
.navi.on::before{content:'';position:absolute;left:-6px;top:10px;bottom:10px;width:5px;border-radius:3px;background:var(--primary);animation:growY .5s var(--spring) both}
.navi .ct{margin-left:auto;font-size:12px;font-weight:760;padding:2px 8px;border-radius:10px;background:var(--surf-high);color:var(--text)}
.navi.dis{opacity:.55}
.rail .sp{flex:1;min-height:12px}
.topbar{padding:22px 28px 10px;display:flex;flex-direction:column;gap:14px}
.tb1{display:flex;align-items:center;gap:12px;flex-wrap:wrap}
.tb1 h1{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0;flex:1;padding:4px 0;font-size:40px;font-weight:800;font-stretch:78%;letter-spacing:-.01em;line-height:1;margin-right:auto}
.srch{display:flex;align-items:center;gap:10px;height:48px;padding:0 8px 0 16px;border-radius:24px;background:var(--glass);backdrop-filter:blur(18px);border:1px solid var(--line);color:var(--sub);font-weight:560;box-shadow:var(--e1);transition:transform .3s var(--spring),box-shadow .3s}
.srch:hover{transform:scale(1.03);box-shadow:var(--e2)}
.srch kbd{font:inherit;font-size:12px;font-weight:700;padding:4px 9px;border-radius:12px;background:var(--surf-high);color:var(--text)}
.icb{position:relative;width:48px;height:48px;border-radius:24px;display:grid;place-items:center;background:var(--glass);border:1px solid var(--line);color:var(--text)!important;transition:transform .3s var(--spring),border-radius .3s var(--spring),background .2s}
.icb:hover{transform:scale(1.08);border-radius:16px;background:var(--primary-c)}
.icb:active{transform:scale(.92)}
.dotb{position:absolute;top:-3px;right:-3px;min-width:20px;height:20px;border-radius:10px;background:var(--bad);color:#fff;font-size:11.5px;font-weight:800;display:grid;place-items:center;padding:0 5px}
.who{display:flex;align-items:center;gap:10px;height:48px;padding:0 16px 0 5px;border-radius:24px;background:var(--glass);border:1px solid var(--line);font-weight:660;font-size:13.5px}
.who b{width:38px;height:38px;display:grid;place-items:center;color:#fff;background:linear-gradient(140deg,var(--b3),var(--b1));clip-path:${SH.flower};font-weight:800}
.tabs{position:relative;display:flex;gap:4px;border-bottom:1px solid var(--line)}
.tabs button{height:48px;padding:0 18px;font-weight:660;color:var(--sub);border-radius:14px 14px 0 0;transition:color .2s,background .2s}
.tabs button:hover{background:var(--surf-high)}
.tabs button[aria-selected=true]{color:var(--primary)}
.tabs .tind{position:absolute;bottom:-1px;height:4px;border-radius:4px 4px 0 0;background:var(--primary);left:0;width:calc(100% / var(--cnt));transform:translateX(calc(var(--idx) * 100%)) scaleX(.5);transition:transform .5s var(--spring)}
.tabs.eq button{flex:1}

/* ---------- type, chips, avatars ---------- */
.disp{font-size:104px;font-weight:800;font-stretch:58%;line-height:.84;letter-spacing:-.025em;font-variant-numeric:tabular-nums}
.disp.m{font-size:64px}.disp.s{font-size:44px}.disp.xl{font-size:150px}
.unit{font-size:22px;font-weight:700;font-stretch:80%;opacity:.86;margin-left:6px}
.kick{display:inline-flex;align-items:center;gap:8px;font-size:12.5px;font-weight:760;letter-spacing:1.1px;text-transform:uppercase}
.sub{color:var(--sub);font-size:13.5px}
.cnt{--v:var(--to);counter-reset:n var(--v)}
.cnt::after{content:counter(n)}
.tag{display:inline-flex;align-items:center;gap:6px;min-height:28px;padding:3px 11px;border-radius:14px;font-size:12.5px;font-weight:720;background:var(--surf-high);color:var(--text);white-space:nowrap}
.tag.good{background:var(--good-c);color:var(--on-good-c)}.tag.warn{background:var(--warn-c);color:var(--on-warn-c)}.tag.bad{background:var(--bad-c);color:var(--on-bad-c)}
.tag.pri{background:var(--primary-c);color:var(--on-primary-c)}.tag.ter{background:var(--tertiary-c);color:var(--on-tertiary-c)}
.tag.live::before{content:'';width:8px;height:8px;border-radius:4px;background:currentColor;animation:pulse 1.8s infinite}
.chips{display:flex;flex-wrap:wrap;gap:8px;align-items:center}
.av{width:44px;height:44px;flex:none;display:grid;place-items:center;font-weight:800;font-size:15px;background:var(--primary-c);color:var(--on-primary-c);border-radius:15px;transition:border-radius .4s var(--spring),transform .4s var(--spring)}
.av.t{background:var(--tertiary-c);color:var(--on-tertiary-c)}.av.s{background:var(--secondary-c);color:var(--on-secondary-c)}.av.g{background:var(--good-c);color:var(--on-good-c)}.av.w{background:var(--warn-c);color:var(--on-warn-c)}.av.b{background:var(--bad-c);color:var(--on-bad-c)}
.av.ink{background:linear-gradient(140deg,var(--f1),var(--b2));color:#fff}
.sh-cookie{clip-path:${SH.cookie};border-radius:0}.sh-clover{clip-path:${SH.clover};border-radius:0}.sh-flower{clip-path:${SH.flower};border-radius:0}.sh-burst{clip-path:${SH.burst};border-radius:0}.sh-blob{clip-path:${SH.blob};border-radius:0}.sh-pill{border-radius:999px}
.morph{animation:morph 14s ease-in-out infinite}

/* ---------- hero ---------- */
.hero{position:relative;isolation:isolate;overflow:hidden;border-radius:40px;padding:34px 36px;display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,1fr);gap:28px;color:#fff;background:linear-gradient(130deg,var(--f1),var(--f2));box-shadow:var(--e2),inset 0 1px 0 rgb(255 255 255 / .25);min-height:330px}
.hero.one{grid-template-columns:1fr}
.aurora{position:absolute;inset:0;z-index:-1;filter:blur(46px) saturate(1.3);pointer-events:none}
.aurora i{position:absolute;display:block;width:46%;aspect-ratio:1.25;border-radius:42% 58% 63% 37%/46% 39% 61% 54%;background:var(--b1);left:-6%;top:-30%;animation:blob1 16s ease-in-out infinite alternate}
.aurora i:nth-child(2){background:var(--b2);left:44%;top:30%;width:52%;animation:blob2 19s ease-in-out infinite alternate}
.aurora i:nth-child(3){background:var(--b3);left:62%;top:-42%;width:38%;opacity:.8;animation:blob3 13s ease-in-out infinite alternate}
.hero::after{content:'';position:absolute;inset:0;z-index:-1;background:radial-gradient(120% 90% at 0% 100%,rgb(0 0 0 / .28),transparent 60%);pointer-events:none}
.hero-l{display:flex;flex-direction:column;gap:14px;justify-content:center;min-width:0}
.hero h2{font-size:46px;font-weight:800;font-stretch:72%;line-height:.98;letter-spacing:-.015em}
.hero .hsub{font-size:16px;font-weight:480;max-width:52ch;opacity:.94}
.hnum{display:flex;align-items:baseline;gap:4px;flex-wrap:wrap}
.hero .tag{background:rgb(255 255 255 / .16);color:#fff;border:1px solid rgb(255 255 255 / .26);backdrop-filter:blur(8px)}
.hero .acts{margin-top:6px}
.hero-r{position:relative;min-width:0;display:flex;flex-direction:column;gap:14px;justify-content:center}
.glass{background:rgb(255 255 255 / .11);backdrop-filter:blur(26px) saturate(1.6);border:1px solid rgb(255 255 255 / .26);box-shadow:inset 0 1px 0 rgb(255 255 255 / .34),0 18px 50px rgb(0 0 0 / .22);border-radius:30px;padding:20px;color:#fff}
.glass .sub,.hero .sub,.ink .sub{color:rgb(255 255 255 / .86)}
.hshape{position:absolute;right:-50px;bottom:-70px;width:240px;height:240px;background:rgb(255 255 255 / .1);z-index:-1}
.acts{display:flex;flex-wrap:wrap;gap:10px;align-items:center}

/* ---------- bento ---------- */
.bento{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:20px;align-items:stretch}
.tile{position:relative;grid-column:span 4;min-width:0;border-radius:32px;padding:22px;background:var(--surf);box-shadow:var(--e1);display:flex;flex-direction:column;gap:14px;transition:transform .45s var(--spring),box-shadow .35s;transform-style:preserve-3d}
.tile:hover{transform:translateY(-5px) perspective(1100px) rotateX(1.2deg) rotateY(-.8deg);box-shadow:var(--e2)}
.w3{grid-column:span 3}.w4{grid-column:span 4}.w5{grid-column:span 5}.w6{grid-column:span 6}.w7{grid-column:span 7}.w8{grid-column:span 8}.w9{grid-column:span 9}.w12{grid-column:span 12}
.r2{grid-row:span 2}
.tile.pri{background:var(--primary-c);color:var(--on-primary-c)}.tile.ter{background:var(--tertiary-c);color:var(--on-tertiary-c)}.tile.sec{background:var(--secondary-c);color:var(--on-secondary-c)}
.tile.pri .sub,.tile.ter .sub,.tile.sec .sub{color:inherit;opacity:.86}
.tile.ink{color:#fff;background:linear-gradient(140deg,var(--f1),var(--b2));overflow:hidden;isolation:isolate}
.tile.ink2{color:#fff;background:linear-gradient(140deg,var(--f2),var(--b3));overflow:hidden;isolation:isolate}
.tile.ink .tic,.tile.ink2 .tic{background:rgb(255 255 255 / .18);color:#fff}
.tile.ink .tag,.tile.ink2 .tag{background:rgb(255 255 255 / .18);color:#fff}
.tile.gl{background:var(--glass);backdrop-filter:blur(24px) saturate(1.5);border:1px solid var(--line)}
.th{display:flex;align-items:center;gap:12px;min-height:44px}
.th h3{font-size:18px;font-weight:760;font-stretch:88%;margin-right:auto;line-height:1.1;flex:1;min-width:0;overflow-wrap:anywhere}
.tic{width:44px;height:44px;flex:none;display:grid;place-items:center;background:var(--primary-c);color:var(--on-primary-c);border-radius:15px;transition:transform .5s var(--spring)}
.tile:hover .tic{transform:rotate(-10deg) scale(1.08)}
.tile.pri .tic,.tile.ter .tic,.tile.sec .tic{background:rgb(255 255 255 / calc(.6 - var(--dark) * .46));color:inherit}
.rise{animation:rise .75s var(--spring) both;animation-delay:calc(var(--i,0) * 70ms)}
.stat{justify-content:space-between}
.stat .lbl{font-size:13px;font-weight:700;letter-spacing:.3px;display:flex;align-items:center;gap:8px}
.stat .delta{font-size:13px;font-weight:760}
.grow{flex:1;min-width:0}
.rowx{display:flex;align-items:center;gap:12px;flex-wrap:wrap}
.colx{display:flex;flex-direction:column;gap:12px;min-width:0}
.split{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}
.split3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}

/* ---------- rows ---------- */
.rows{display:flex;flex-direction:column;gap:8px}
.row{display:flex;align-items:center;gap:12px;min-height:60px;padding:8px 12px 8px 8px;border-radius:22px;background:var(--surf-low);animation:rise .6s var(--spring) both;animation-delay:calc(var(--j,0) * 55ms + 200ms);transition:background .2s,transform .35s var(--spring),border-radius .35s var(--spring)}
.row:hover{background:var(--surf-high);transform:translateX(4px);border-radius:16px}
.row:hover .av{border-radius:22px;transform:rotate(-6deg)}
.tile.pri .row,.tile.ter .row,.tile.sec .row{background:rgb(255 255 255 / calc(.5 - var(--dark) * .42))}
.tile.ink .row,.tile.ink2 .row,.glass .row{background:rgb(255 255 255 / .12)}
.t1{font-weight:700;font-size:14.5px;line-height:1.2;overflow-wrap:anywhere}
.t2{font-size:12.5px;color:var(--sub);line-height:1.25;overflow-wrap:anywhere}
.tile.pri .t2,.tile.ter .t2,.tile.sec .t2{color:inherit;opacity:.82}.ink .t2,.ink2 .t2,.glass .t2,.hero .t2{color:rgb(255 255 255 / .86)}
.mono{font-family:ui-monospace,Consolas,monospace;font-size:12.5px}

/* ---------- buttons ---------- */
.btn{position:relative;overflow:hidden;display:inline-flex;align-items:center;justify-content:center;gap:9px;min-height:48px;padding:0 22px!important;border-radius:24px;font-weight:720!important;font-size:14.5px;text-decoration:none;white-space:nowrap;transition:transform .3s var(--spring),border-radius .35s var(--spring),box-shadow .3s,filter .2s;isolation:isolate}
.btn::after{content:'';position:absolute;inset:0;z-index:-1;background:radial-gradient(circle,currentColor 10%,transparent 11%) center/1200% 1200%;opacity:0;transition:background-size .6s,opacity .8s}
.btn:active::after{background-size:0 0;opacity:.3;transition:0s}
.btn:hover{transform:translateY(-2px);border-radius:16px;box-shadow:var(--e2)}
.btn:active{transform:scale(.94)}
.btn.fill{background:var(--primary)!important;color:var(--on-primary)!important}
.btn.ton{background:var(--primary-c)!important;color:var(--on-primary-c)!important}
.btn.out{box-shadow:inset 0 0 0 1.5px var(--line);color:var(--text)!important}
.btn.wh{background:#fff!important;color:var(--f1)!important}
.btn.gh{background:rgb(255 255 255 / .16)!important;color:#fff!important;border:1px solid rgb(255 255 255 / .3)!important}
.btn.dng{background:var(--bad)!important;color:#fff!important}
.btn.sm{min-height:44px;padding:0 16px!important;font-size:13.5px}
.hot{overflow:visible}
.hot::before{content:'';position:absolute;inset:-4px;border-radius:inherit;z-index:-2;background:conic-gradient(from var(--ang),var(--b1),#fff,var(--b3),var(--b2),var(--b1));animation:spinang 3.2s linear infinite;filter:blur(1px)}
.hot::after{content:'';position:absolute;inset:0;border-radius:inherit;background:inherit;opacity:1;z-index:-1}

/* ---------- controls ---------- */
.fld{display:flex;align-items:center;gap:14px;flex-wrap:wrap;min-height:56px;padding:6px 0}
.fld+.fld{border-top:1px solid var(--line)}
.fld .fl{flex:1 1 180px;min-width:0}
.sw{position:relative;width:60px;height:36px;border-radius:18px;background:var(--surf-high)!important;box-shadow:inset 0 0 0 2px var(--sub);flex:none;transition:background .3s,box-shadow .3s;margin:4px 0!important}
.sw i{position:absolute;top:8px;left:8px;width:20px;height:20px;border-radius:10px;background:var(--sub);transition:transform .5s var(--spring),width .3s,background .3s,top .3s,height .3s;display:grid;place-items:center}
.sw:active i{width:28px}
.sw.on{background:var(--primary)!important;box-shadow:none}
.sw.on i{transform:translateX(22px);background:var(--on-primary);top:5px;left:6px;width:26px;height:26px;border-radius:13px}
.sw.on i::after{content:'';width:10px;height:6px;border-left:2.4px solid var(--primary);border-bottom:2.4px solid var(--primary);transform:rotate(-45deg) translate(1px,-1px)}
.seg{position:relative;display:inline-grid;grid-auto-flow:column;grid-auto-columns:minmax(0,1fr);padding:4px;border-radius:26px;background:var(--surf-high);min-height:52px;max-width:100%}
.seg .ind{position:absolute;top:4px;bottom:4px;left:4px;width:calc((100% - 8px) / var(--cnt));border-radius:22px;background:var(--primary);box-shadow:var(--e1);transform:translateX(calc(var(--idx) * 100%));transition:transform .55s var(--spring)}
.seg button{position:relative;z-index:1;min-height:44px;padding:0 16px;font-weight:700;font-size:13.5px;color:var(--text);border-radius:22px;transition:color .25s,transform .25s var(--spring);white-space:nowrap}
.seg button:active{transform:scale(.92)}
.seg button[aria-pressed=true]{color:var(--on-primary)}
.ink .seg,.ink2 .seg,.glass .seg,.hero .seg{background:rgb(255 255 255 / .16)}.ink .seg button,.ink2 .seg button,.glass .seg button,.hero .seg button{color:#fff}
.ink .seg .ind,.ink2 .seg .ind,.glass .seg .ind,.hero .seg .ind{background:#fff}.ink .seg button[aria-pressed=true],.ink2 .seg button[aria-pressed=true],.glass .seg button[aria-pressed=true],.hero .seg button[aria-pressed=true]{color:var(--f1)}
.seg.wide{display:grid;width:100%}
.sl{display:flex;align-items:center;gap:10px;flex:1 1 240px;min-width:200px}
.sl input{appearance:none;-webkit-appearance:none;flex:1;min-width:0;height:44px;background:none;margin:0;cursor:pointer}
.sl input::-webkit-slider-runnable-track{height:18px;border-radius:9px;background:linear-gradient(90deg,var(--primary) var(--p),var(--surf-high) var(--p))}
.sl input::-webkit-slider-thumb{-webkit-appearance:none;width:8px;height:44px;border-radius:4px;background:var(--primary);margin-top:-13px;box-shadow:0 0 0 5px var(--surf);transition:width .2s,transform .3s var(--spring)}
.sl input:active::-webkit-slider-thumb{width:4px}
.sl output,.stp output{min-width:64px;text-align:center;font-weight:800;font-size:17px;font-stretch:80%;font-variant-numeric:tabular-nums}
.sl output small,.stp output small{font-size:11.5px;font-weight:700;opacity:.75;margin-left:3px}
.stp{display:inline-flex;align-items:center;gap:2px;padding:4px;border-radius:26px;background:var(--surf-high)}
.stp button{width:44px;height:44px;border-radius:22px;background:var(--surf);font-size:22px;font-weight:600;line-height:1;box-shadow:var(--e1);transition:transform .3s var(--spring),border-radius .3s var(--spring),background .2s}
.stp button:hover{background:var(--primary-c);border-radius:14px}.stp button:active{transform:scale(.85)}
.ink .stp,.ink2 .stp,.glass .stp,.hero .stp{background:rgb(255 255 255 / .16)}.ink .stp button,.ink2 .stp button,.glass .stp button,.hero .stp button{background:rgb(255 255 255 / .22);color:#fff}
.ipp{display:inline-flex;align-items:center;gap:4px;flex-wrap:wrap}
.ipp .oc{min-width:50px;height:52px;padding:0 8px;border-radius:16px;background:var(--surf-high);display:grid;place-items:center;font-weight:800;font-size:17px;font-stretch:80%;color:var(--sub)}
.ipp .dot{font-weight:900;color:var(--sub)}
.bits{display:flex;height:16px;border-radius:8px;overflow:hidden;background:var(--tertiary-c);flex:1 1 160px;min-width:140px}
.bits i{display:block;width:var(--p);background:linear-gradient(90deg,var(--primary),var(--b1));border-radius:8px;transition:width .6s var(--spring)}
.chip{display:inline-flex;align-items:center;gap:0;min-height:44px;padding:0 16px;border-radius:14px;font-weight:680;font-size:13.5px;box-shadow:inset 0 0 0 1.5px var(--line);background:var(--surf);color:var(--text);transition:transform .3s var(--spring),border-radius .35s var(--spring),background .25s,padding .3s var(--spring),gap .3s;white-space:nowrap}
.chip::before{content:'';width:0;height:7px;border-left:0 solid;border-bottom:0 solid;transform:rotate(-45deg) translateY(-2px);transition:width .3s var(--spring),border-width .2s}
.chip:hover{transform:translateY(-2px)}.chip:active{transform:scale(.92)}
.chip.on,.chip[aria-pressed=true]{background:var(--secondary-c);color:var(--on-secondary-c);box-shadow:none;border-radius:22px;gap:8px}
.chip.on::before,.chip[aria-pressed=true]::before{width:12px;border-left-width:2.4px;border-bottom-width:2.4px}
.ink .chip,.ink2 .chip,.glass .chip,.hero .chip{background:rgb(255 255 255 / .12);color:#fff;box-shadow:inset 0 0 0 1.5px rgb(255 255 255 / .3)}
.ink .chip[aria-pressed=true],.ink2 .chip[aria-pressed=true],.glass .chip[aria-pressed=true],.hero .chip[aria-pressed=true],.glass .chip.on,.hero .chip.on{background:#fff;color:var(--f1)}
.devp{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:8px;width:100%}
.devp button{display:flex;align-items:center;gap:10px;min-height:60px;padding:8px 10px;border-radius:20px;background:var(--surf-low);text-align:left;box-shadow:inset 0 0 0 0 var(--primary);transition:box-shadow .3s,transform .3s var(--spring),background .2s,border-radius .3s var(--spring)}
.devp button:hover{transform:translateY(-2px)}
.devp button[aria-pressed=true]{background:var(--primary-c);color:var(--on-primary-c);box-shadow:inset 0 0 0 2.5px var(--primary);border-radius:14px}
.devp button[aria-pressed=true] .av{background:var(--primary);color:var(--on-primary);clip-path:${SH.cookie}}
.glass .devp button,.ink .devp button{background:rgb(255 255 255 / .14);color:#fff}.glass .devp button .t2,.ink .devp button .t2{color:rgb(255 255 255 / .85)}.glass .devp button[aria-pressed=true],.ink .devp button[aria-pressed=true]{background:#fff;color:var(--f1);box-shadow:none}.glass .devp button[aria-pressed=true] .t2,.ink .devp button[aria-pressed=true] .t2{color:var(--f1)}
.pw{display:flex;align-items:center;gap:10px;flex-wrap:wrap;flex:1 1 260px}
.pw .pv{min-height:52px;flex:1 1 150px;display:flex;align-items:center;padding:0 16px;border-radius:16px;background:var(--surf-high);font-weight:700;letter-spacing:2px}
.pw .str{flex:1 1 100%;display:flex;align-items:center;gap:10px;font-size:12.5px;font-weight:700}
.pw .str span{flex:1;height:8px;border-radius:4px;background:var(--surf-high);overflow:hidden}
.pw .str span i{display:block;height:100%;width:var(--p);border-radius:4px;background:linear-gradient(90deg,var(--warn),var(--good));animation:growX 1s var(--ease) both}
.nm{display:flex;align-items:center;gap:10px;flex:1 1 240px;min-height:52px;padding:0 14px 0 16px;border-radius:16px;background:var(--surf-high);box-shadow:inset 0 -2px 0 var(--primary);transition:box-shadow .3s}
.nm:focus-within{box-shadow:inset 0 0 0 2.5px var(--primary)}
.nm input{flex:1;min-width:0;height:48px;border:0;background:none;font:inherit;font-weight:700;color:inherit;outline:0}
.nm .cn{font-size:12px;font-weight:700;color:var(--sub);white-space:nowrap}
.hint{display:flex;align-items:center;gap:6px;font-size:12.5px;color:var(--good);font-weight:650;flex-basis:100%}
.role-viewer .w,.role-viewer .w *{pointer-events:none}
.role-viewer .w{opacity:.48;filter:saturate(.4)}
.ro{display:flex;align-items:center;gap:12px;padding:12px 18px;border-radius:20px;background:var(--warn-c);color:var(--on-warn-c);font-weight:650;font-size:13.5px;animation:rise .6s var(--spring) both}
.mo{position:relative}
.fw-stock .mo>*:not(.molock){opacity:.35;pointer-events:none;filter:saturate(.3)}
.molock{display:none}
.fw-stock .molock{display:flex;position:absolute;inset:auto 12px 12px 12px;z-index:3;align-items:center;gap:10px;padding:12px 16px;border-radius:18px;background:var(--surf);color:var(--text);box-shadow:var(--e2);font-weight:650;font-size:13px;animation:rise .6s var(--spring) both}

/* paint grid */
.pg{display:flex;flex-direction:column;gap:3px;--c:24;overflow-x:auto;padding-bottom:4px}
.pg .pr{display:grid;grid-template-columns:56px repeat(var(--c),minmax(18px,1fr));gap:3px;align-items:center}
.pg .pl{font-size:12px;font-weight:750;color:var(--sub)}
.pg button{height:30px;border-radius:7px;background:var(--surf-high);transition:background .25s,transform .3s var(--spring),border-radius .3s var(--spring)}
.pg button:hover{transform:scale(1.25);z-index:1;border-radius:10px}
.pg button.on{background:linear-gradient(160deg,var(--b1),var(--primary));animation:pop .4s var(--spring)}
.pg button.an{box-shadow:0 0 0 3px var(--tertiary);border-radius:50%}
.pg .hr{font-size:10.5px;font-weight:700;color:var(--sub);text-align:center}

/* ---------- visuals ---------- */
.ch{display:block;width:100%;overflow:hidden}
.ch .ln{fill:none;stroke-width:3.5;stroke-linecap:round;stroke-linejoin:round;vector-effect:non-scaling-stroke;stroke-dasharray:1;stroke-dashoffset:0;animation:draw 1.8s var(--ease) both .2s}
.ch .ar{animation:fade 1.2s ease both .7s}
.ch .swp{animation:sweep 2.4s var(--ease) both .3s}
.ch .dt{stroke-width:12;stroke-linecap:round;vector-effect:non-scaling-stroke;animation:pulse 1.8s infinite}
.ch .gr{stroke:currentColor;stroke-opacity:.14;stroke-width:1;vector-effect:non-scaling-stroke;stroke-dasharray:3 5}
.axis{display:flex;justify-content:space-between;font-size:11.5px;font-weight:650;opacity:.78}
.bars{display:flex;align-items:flex-end;gap:6px;height:var(--h,110px)}
.bars i{flex:1;height:var(--b);min-height:6px;border-radius:8px 8px 4px 4px;background:linear-gradient(180deg,var(--b1),var(--primary));transform-origin:bottom;animation:growY .9s var(--spring) both;animation-delay:calc(var(--k) * 45ms + 250ms)}
.bars i.lo{background:var(--surf-high)}
.ink .bars i,.ink2 .bars i,.glass .bars i{background:linear-gradient(180deg,#fff,rgb(255 255 255 / .45))}
.hb{display:flex;flex-direction:column;gap:10px}
.hb div{display:grid;grid-template-columns:minmax(80px,130px) 1fr 54px;gap:10px;align-items:center;font-size:13px;font-weight:650}
.hb span{height:14px;border-radius:7px;background:var(--surf-high);overflow:hidden}
.hb span i{display:block;height:100%;width:var(--b);border-radius:7px;background:linear-gradient(90deg,var(--primary),var(--b1));transform-origin:left;animation:growX 1.1s var(--spring) both;animation-delay:calc(var(--k) * 80ms + 300ms)}
.hb b{text-align:right;font-variant-numeric:tabular-nums}
.gauge{position:relative;width:var(--s,180px);aspect-ratio:1;flex:none;display:grid;place-items:center}
.gauge svg{position:absolute;inset:0;width:100%;height:100%;transform:rotate(135deg)}
.gauge .trk{fill:none;stroke:currentColor;stroke-opacity:.16;stroke-width:9;stroke-linecap:round;stroke-dasharray:75 100}
.gauge .val{fill:none;stroke-width:9;stroke-linecap:round;stroke-dasharray:calc(var(--p) * .75) 100;animation:gauge 1.6s var(--ease) both .3s}
.gauge.full svg{transform:rotate(-90deg)}.gauge.full .trk{stroke-dasharray:100 100}.gauge.full .val{stroke-dasharray:var(--p) 100}
.gauge .gc{position:relative;text-align:center;display:flex;flex-direction:column;align-items:center}
.gauge .gc small{font-size:12px;font-weight:700;opacity:.82}
.heat{display:grid;grid-template-columns:repeat(var(--c),1fr);gap:4px}
.heat i{aspect-ratio:1;border-radius:6px;background:var(--primary);opacity:var(--o);animation:pop .5s var(--spring) both;animation-delay:calc(var(--k) * 9ms + 200ms)}
.ink .heat i,.ink2 .heat i,.glass .heat i{background:#fff}
.spark{display:block;width:100%;height:44px}
.spark path{fill:none;stroke:currentColor;stroke-width:3;stroke-linecap:round;stroke-linejoin:round;vector-effect:non-scaling-stroke;stroke-dasharray:1;animation:draw 1.5s var(--ease) both .4s}
.radar{position:relative;width:var(--s,230px);aspect-ratio:1;border-radius:50%;flex:none;background:repeating-radial-gradient(circle,transparent 0 19%,rgb(255 255 255 / .22) 19% 19.6%),radial-gradient(circle,rgb(255 255 255 / .16),rgb(255 255 255 / .04));overflow:hidden;box-shadow:inset 0 0 0 2px rgb(255 255 255 / .3)}
.radar::before{content:'';position:absolute;inset:0;border-radius:50%;background:conic-gradient(from var(--ang),rgb(255 255 255 / .75),transparent 28%);animation:spinang 2.6s linear infinite}
.radar b{position:absolute;width:12px;height:12px;border-radius:6px;background:#fff;left:var(--x);top:var(--y);box-shadow:0 0 0 0 rgb(255 255 255 / .7);animation:blip 2.6s infinite;animation-delay:var(--d)}
.map{display:block;width:100%;height:auto}
.map .lk{fill:none;stroke:currentColor;stroke-opacity:.34;stroke-width:3;stroke-linecap:round;stroke-dasharray:1;animation:draw 1.4s var(--ease) both .2s}
.map .lk.weak{stroke-dasharray:.02 .03;stroke:var(--warn);stroke-opacity:.9;animation:none}
.map .pk{fill:var(--b1);offset-rotate:0deg;animation:flow var(--d,2.6s) linear infinite;animation-delay:var(--dl,0s)}
.map .nd{animation:pop .7s var(--spring) both;animation-delay:calc(var(--k) * 90ms + 200ms);transform-box:fill-box;transform-origin:center}
.map text{font-family:var(--font);font-size:18px;font-weight:700;fill:currentColor;text-anchor:middle}
.map .n0{fill:var(--primary)}.map .n1{fill:var(--surf);stroke:var(--primary);stroke-width:2.5}.map .n2{fill:var(--tertiary-c);stroke:var(--tertiary);stroke-width:2}
.wave{display:block;width:100%;height:22px}
.wave path{fill:none;stroke:var(--primary);stroke-width:5;stroke-linecap:round;animation:waveX 1.6s linear infinite}
.prog{display:block;height:14px;border-radius:7px;background:var(--surf-high);overflow:hidden}
.prog i{display:block;height:100%;width:var(--p);border-radius:7px;background:linear-gradient(90deg,var(--primary),var(--b1),var(--primary));background-size:200% 100%;animation:growX 1.2s var(--spring) both,shim 2.4s linear infinite}
.ink .prog,.ink2 .prog,.glass .prog,.hero .prog{background:rgb(255 255 255 / .2)}.ink .prog i,.ink2 .prog i,.glass .prog i,.hero .prog i{background:linear-gradient(90deg,#fff,rgb(255 255 255 / .6),#fff);background-size:200% 100%}
.qr{width:var(--s,150px);aspect-ratio:1;border-radius:18px;background:#fff;padding:12px;display:grid;grid-template-columns:repeat(11,1fr);gap:2px;flex:none}
.qr i{border-radius:2px;background:#16161d;animation:pop .4s var(--spring) both;animation-delay:calc(var(--k) * 6ms + 300ms)}
.qr i.o{background:none}
.pipe{display:flex;align-items:center;gap:0;flex-wrap:wrap;row-gap:10px}
.pipe .ps{display:flex;align-items:center;gap:10px;font-weight:700;font-size:13.5px}
.pipe .pn{width:44px;height:44px;display:grid;place-items:center;border-radius:22px;background:var(--surf-high);font-weight:800;transition:all .5s var(--spring)}
.pipe .ps.done .pn{background:var(--good-c);color:var(--on-good-c)}
.pipe .ps.now .pn{background:var(--primary);color:var(--on-primary);clip-path:${SH.cookie};animation:spin 9s linear infinite}
.pipe .pc{flex:1 1 24px;min-width:24px;height:4px;border-radius:2px;background:var(--surf-high);margin:0 10px;overflow:hidden}
.pipe .pc.done{background:var(--good)}
.pipe .pc.now{background:linear-gradient(90deg,var(--primary),var(--surf-high),var(--primary));background-size:200% 100%;animation:shim 1.4s linear infinite}
.ink .pipe .pn,.glass .pipe .pn,.hero .pipe .pn{background:rgb(255 255 255 / .18)}.glass .pipe .ps.now .pn,.hero .pipe .ps.now .pn,.ink .pipe .ps.now .pn{background:#fff;color:var(--f1)}.glass .pipe .pc,.hero .pipe .pc{background:rgb(255 255 255 / .22)}
.ring{position:relative;display:grid;place-items:center;width:var(--s,200px);aspect-ratio:1;flex:none}
.ring svg{position:absolute;inset:0;width:100%;height:100%}
.ring .wv{fill:none;stroke:currentColor;stroke-width:2.6;stroke-linejoin:round;transform-origin:50px 50px;animation:spin 12s linear infinite}
.ring .wv2{fill:none;stroke:currentColor;stroke-opacity:.35;stroke-width:1.6;transform-origin:50px 50px;animation:spin 20s linear infinite reverse}
.term{font-family:ui-monospace,Consolas,monospace;font-size:12.5px;line-height:1.7;background:#11131c;color:#d7dcf5;border-radius:22px;padding:16px 18px;overflow:hidden}
.term div{animation:rise .5s var(--ease) both;animation-delay:calc(var(--j) * 140ms + 300ms);white-space:pre-wrap;overflow-wrap:anywhere}
.term .ok{color:#7be0a4}.term .er{color:#ff9a8f}.term .dm{color:#8f96bd}.term .hl{color:#ffd479}
.term .cur::after{content:'';display:inline-block;width:8px;height:15px;background:#d7dcf5;vertical-align:-2px;margin-left:3px;animation:blink 1s steps(2) infinite}

/* ---------- stages ---------- */
.stagebar{display:flex;align-items:center;gap:12px;flex-wrap:wrap;font-size:12.5px;font-weight:720;color:var(--sub)}
.sk{border-radius:32px;min-height:var(--h,180px);background:linear-gradient(100deg,var(--surf-high) 30%,var(--surf) 50%,var(--surf-high) 70%);background-size:300% 100%;animation:shim 1.5s linear infinite,rise .6s var(--spring) both;animation-delay:0s,calc(var(--i,0) * 70ms)}
.empty{position:relative;border-radius:40px;padding:56px 36px;display:flex;flex-direction:column;align-items:center;gap:16px;text-align:center;background:var(--surf);box-shadow:var(--e1);overflow:hidden;isolation:isolate}
.empty .eshape{width:150px;height:150px;display:grid;place-items:center;color:#fff;background:linear-gradient(140deg,var(--b1),var(--f1));animation:morph 9s ease-in-out infinite}
.empty h2{font-size:34px;font-weight:800;font-stretch:76%}
.empty p{max-width:56ch;color:var(--sub)}
.banner{position:relative;display:flex;align-items:center;gap:18px;flex-wrap:wrap;border-radius:32px;padding:20px 24px;overflow:hidden;isolation:isolate}
.banner.ok{background:var(--good-c);color:var(--on-good-c);animation:rise .7s var(--spring) both}
.banner.no{background:var(--bad-c);color:var(--on-bad-c);animation:shake .6s both}
.banner h2{font-size:24px;font-weight:800;font-stretch:80%}
.banner .reason{flex-basis:100%;display:flex;align-items:center;gap:10px;font-weight:650;animation:slideIn .7s var(--spring) both .5s}
.okmark{position:relative;width:72px;height:72px;flex:none;display:grid;place-items:center}
.okmark .bg{position:absolute;inset:0;background:var(--good);clip-path:${SH.cookie};animation:pop .7s var(--spring) both,spin 14s linear infinite}
.okmark svg{position:relative;width:38px;height:38px}
.okmark path{fill:none;stroke:#fff;stroke-width:3.4;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:1;animation:draw .7s var(--ease) both .45s}
.burst{position:absolute;left:60px;top:50%;width:0;height:0;pointer-events:none}
.burst i{position:absolute;width:16px;height:16px;margin:-8px;background:var(--c,var(--good));clip-path:${SH.flower};animation:burst 1.3s var(--ease) both .3s;--tx:calc(cos(var(--a)) * var(--r));--ty:calc(sin(var(--a)) * var(--r))}
.burst i:nth-child(odd){clip-path:${SH.round};width:10px;height:10px}
.nomark{position:relative;width:72px;height:72px;flex:none;display:grid;place-items:center;border-radius:36px;background:var(--bad);color:#fff}
.nomark::before{content:'';position:absolute;inset:0;border-radius:50%;box-shadow:0 0 0 0 var(--bad);animation:redpulse 1.5s 3}

/* ---------- dock, sheet, dialog, toast ---------- */
.dock{position:sticky;bottom:20px;z-index:5;display:flex;align-items:center;gap:14px;flex-wrap:wrap;padding:12px 14px 12px 22px;border-radius:36px;background:oklch(from var(--accent) calc(.22 + var(--dark) * .7) .05 h);color:oklch(from var(--accent) calc(.96 - var(--dark) * .76) .02 h);box-shadow:var(--e3);animation:dockIn .7s var(--spring) both;margin-top:auto}
.dock .dn{font-weight:800;font-size:16px;margin-right:auto;display:flex;align-items:center;gap:12px}
.dock .dn b{min-width:36px;height:36px;border-radius:18px;display:grid;place-items:center;background:var(--b1);color:#fff;padding:0 8px;animation:pop .5s var(--spring)}
.dock .btn.out{color:inherit!important;box-shadow:inset 0 0 0 1.5px currentColor}
.scrim{position:absolute;inset:0;z-index:8;background:rgb(8 10 28 / .5);backdrop-filter:blur(6px);animation:fade .35s ease both;display:grid;place-items:center;padding:24px}
.scrim.end{place-items:stretch end;padding:0}
.dialog{width:min(640px,100%);border-radius:40px;background:var(--surf);color:var(--text);box-shadow:var(--e3);padding:28px;display:flex;flex-direction:column;gap:16px;animation:dlg .6s var(--spring) both}
.sheet{width:min(520px,100%);height:100%;background:var(--surf);color:var(--text);box-shadow:var(--e3);padding:28px;display:flex;flex-direction:column;gap:16px;border-radius:40px 0 0 40px;animation:sheetX .6s var(--spring) both;overflow:auto}
.bsheet{position:absolute;left:0;right:0;bottom:0;z-index:9;border-radius:36px 36px 0 0;background:var(--surf);box-shadow:var(--e3);padding:12px 18px 22px;display:flex;flex-direction:column;gap:12px;animation:sheetY .65s var(--spring) both}
.bsheet::before{content:'';width:44px;height:5px;border-radius:3px;background:var(--line);align-self:center}
.dialog h2,.sheet h2{font-size:28px;font-weight:800;font-stretch:78%}
.diff{display:grid;grid-template-columns:1fr auto 1fr;gap:10px;align-items:center;padding:10px 12px;border-radius:18px;background:var(--surf-low);animation:rise .5s var(--spring) both;animation-delay:calc(var(--j) * 70ms + 200ms)}
.diff .old{color:var(--on-bad-c);background:var(--bad-c);padding:5px 10px;border-radius:10px;font-weight:700;font-size:13px;text-decoration:line-through;justify-self:start}
.diff .new{color:var(--on-good-c);background:var(--good-c);padding:5px 10px;border-radius:10px;font-weight:700;font-size:13px;justify-self:start}
.diff .dk{grid-column:1 / -1;font-size:12.5px;font-weight:700;color:var(--sub)}
.toast{display:flex;align-items:center;gap:12px;padding:12px 16px;border-radius:22px;background:oklch(from var(--accent) calc(.24 + var(--dark) * .68) .05 h);color:oklch(from var(--accent) calc(.96 - var(--dark) * .76) .02 h);box-shadow:var(--e3);font-weight:650;font-size:13.5px;animation:toastIn .7s var(--spring) both;animation-delay:calc(var(--j,0) * 160ms + 300ms)}

/* ---------- editors ---------- */
.stage{position:relative;border-radius:28px;background:radial-gradient(circle at 1px 1px,var(--line) 1.2px,transparent 1.6px) 0 0/22px 22px,var(--surf-low);padding:18px;overflow:hidden}
.pick{box-shadow:0 0 0 3px var(--tertiary),var(--e2)!important;transform:scale(1.04) rotate(-1.5deg)!important;z-index:2}
.drop{outline:3px dashed var(--tertiary);outline-offset:-3px;animation:breathe 1.2s ease-in-out infinite}
.card{display:flex;align-items:center;gap:10px;min-height:56px;padding:8px 12px 8px 8px;border-radius:20px;background:var(--surf);box-shadow:var(--e1);text-align:left;width:100%;transition:transform .4s var(--spring),box-shadow .3s,border-radius .3s var(--spring);animation:rise .6s var(--spring) both;animation-delay:calc(var(--j,0) * 60ms + 200ms)}
.card:hover{transform:translateY(-3px) rotate(-.6deg);box-shadow:var(--e2)}
.card.bad{box-shadow:inset 0 0 0 2.5px var(--bad),var(--e1);animation:rise .6s var(--spring) both,shake .6s .9s both}
.grip{width:20px;height:28px;flex:none;opacity:.55;background:radial-gradient(circle,currentColor 1.6px,transparent 2px) 0 0/10px 9px}
.lanes{display:grid;grid-template-columns:repeat(var(--c,3),minmax(0,1fr));gap:14px}
.lane{border-radius:26px;background:var(--surf-low);padding:14px;display:flex;flex-direction:column;gap:10px;min-height:200px;transition:background .3s}
.lane h4{margin:0;font-size:13px;font-weight:800;letter-spacing:.6px;text-transform:uppercase;display:flex;align-items:center;gap:8px;min-height:44px}
.spec{position:relative;height:240px;border-radius:24px;background:linear-gradient(180deg,transparent,oklch(from var(--accent) .5 .1 h / .1)),var(--surf-low);overflow:hidden}
.spec svg{position:absolute;inset:0;width:100%;height:100%}
.spec .nb{fill:var(--sub);fill-opacity:.22;stroke:var(--sub);stroke-opacity:.6;stroke-width:1.5;vector-effect:non-scaling-stroke;transform-origin:bottom;animation:growY 1s var(--spring) both;animation-delay:calc(var(--k) * 90ms)}
.spec .me{fill:url(#meg);stroke:var(--primary);stroke-width:3;vector-effect:non-scaling-stroke;transition:d .6s var(--spring);animation:breathe 2.4s ease-in-out infinite}
.chrow{display:grid;grid-template-columns:repeat(var(--c),minmax(0,1fr));gap:4px}
.chrow button{min-height:44px;border-radius:12px;background:var(--surf-high);font-weight:750;font-size:13px;transition:all .35s var(--spring)}
.chrow button:hover{transform:translateY(-3px)}
.chrow button[aria-pressed=true]{background:var(--primary);color:var(--on-primary);border-radius:22px}
.chrow button.in{background:var(--primary-c);color:var(--on-primary-c)}
.back{display:grid;grid-template-columns:repeat(var(--c,6),minmax(0,1fr));gap:12px;padding:22px;border-radius:28px;background:linear-gradient(180deg,#23252f,#12131a);color:#fff;box-shadow:inset 0 2px 0 rgb(255 255 255 / .12),var(--e2)}
.port{display:flex;flex-direction:column;align-items:center;gap:8px;padding:12px 6px;border-radius:18px;background:rgb(255 255 255 / .07);min-height:150px;transition:all .4s var(--spring)}
.port:hover{transform:translateY(-4px);background:rgb(255 255 255 / .14)}
.port .jack{width:56px;height:44px;border-radius:8px 8px 4px 4px;background:#05060a;box-shadow:inset 0 -8px 0 var(--pc,#555),inset 0 0 0 2px rgb(255 255 255 / .25);position:relative}
.port .jack::after{content:'';position:absolute;top:-6px;right:6px;width:8px;height:8px;border-radius:4px;background:var(--pc,#555);animation:pulse 1.6s infinite}
.port small{font-size:11.5px;font-weight:700;opacity:.85;text-align:center}
.port b{font-size:13px}
.cells{display:grid;grid-template-columns:repeat(32,minmax(0,1fr));gap:3px}
.cells button{aspect-ratio:1;min-width:0;border-radius:5px;background:var(--surf-high);animation:pop .4s var(--spring) both;animation-delay:calc(var(--k) * 3ms);transition:transform .25s var(--spring),border-radius .25s}
.cells button:hover{transform:scale(1.5);z-index:2;border-radius:50%}
.cells .pool{background:var(--primary-c);box-shadow:inset 0 0 0 1.5px var(--primary)}
.cells .lease{background:var(--primary)}.cells .resv{background:var(--tertiary)}.cells .rtr{background:var(--bad);clip-path:${SH.cookie}}.cells .edge{box-shadow:0 0 0 3px var(--warn);border-radius:50%;z-index:1}
.lg{display:flex;flex-wrap:wrap;gap:14px;font-size:12.5px;font-weight:700}
.lg span{display:flex;align-items:center;gap:7px}.lg i{width:14px;height:14px;border-radius:4px;background:var(--surf-high)}
.modec{position:relative;overflow:hidden;isolation:isolate;display:flex;flex-direction:column;gap:12px;align-items:flex-start;text-align:left;border-radius:36px;padding:22px;min-height:250px;color:#fff;background:linear-gradient(145deg,oklch(.42 .17 var(--hh)),oklch(.3 .14 calc(var(--hh) - 40)));box-shadow:var(--e2);transition:transform .5s var(--spring),border-radius .5s var(--spring),box-shadow .3s;animation:rise .8s var(--spring) both;animation-delay:calc(var(--i) * 80ms)}
.modec:hover{transform:translateY(-8px) rotate(-1deg) scale(1.02);border-radius:52px;box-shadow:var(--e3)}
.modec:active{transform:scale(.96)}
.modec .ms{position:absolute;right:-34px;top:-34px;width:150px;height:150px;background:oklch(.62 .2 calc(var(--hh) + 40) / .7);z-index:-1;transition:transform .8s var(--spring)}
.modec:hover .ms{transform:rotate(60deg) scale(1.25)}
.modec .mi{width:60px;height:60px;display:grid;place-items:center;background:rgb(255 255 255 / .2);border:1px solid rgb(255 255 255 / .3);backdrop-filter:blur(8px);border-radius:20px}
.modec h3{font-size:28px;font-weight:800;font-stretch:76%;line-height:1}
.modec p{font-size:13.5px;opacity:.92}
.modec.act{box-shadow:0 0 0 4px var(--bg),0 0 0 8px oklch(.62 .2 var(--hh)),var(--e3)}
.modec.act .ms{animation:morph 8s ease-in-out infinite}
.modec .mfoot{margin-top:auto;display:flex;align-items:center;gap:8px;flex-wrap:wrap;width:100%}
.modec .tag{background:rgb(255 255 255 / .18);color:#fff}

.mapst{aspect-ratio:1000 / 540;padding:0}
.mnode{position:absolute;transform:translate(-50%,-50%);display:flex;flex-direction:column;align-items:center;gap:3px;padding:10px 16px;border-radius:28px;background:var(--surf)!important;box-shadow:var(--e2);z-index:1;min-width:130px;transition:transform .4s var(--spring)}
.mnode:hover{transform:translate(-50%,-50%) scale(1.07)}
.mnode.rt .av{width:60px;height:60px;clip-path:${SH.cookie}}
.mdev{position:absolute;transform:translate(-50%,-50%);display:flex;flex-direction:column;align-items:center;gap:3px;z-index:2;transition:left .9s var(--spring),top .9s var(--spring),transform .4s var(--spring)}
.mdev .av{width:52px;height:52px;border-radius:50%;box-shadow:var(--e1);background:var(--surf);color:var(--text);transition:all .4s var(--spring)}
.mdev .t2{background:var(--surf);padding:1px 8px;border-radius:9px;font-weight:700;color:var(--text)}
.mdev:hover{transform:translate(-50%,-50%) scale(1.12)}
.mdev.pick{transform:translate(-50%,-50%) scale(1.2)!important;box-shadow:none!important}
.mdev.pick .av{background:var(--tertiary);color:#fff;box-shadow:0 0 0 5px var(--tertiary-c),var(--e2);clip-path:none}
.mdev.blk .av{background:var(--bad-c);color:var(--on-bad-c)}
.flowbar{display:flex;align-items:center;gap:12px}
.flowbar i{flex:1;height:6px;border-radius:3px;background:repeating-linear-gradient(90deg,var(--primary) 0 14px,transparent 14px 28px);animation:dash .7s linear infinite}
.card.off{opacity:.62}
.dirst{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.1fr) minmax(0,1fr);height:540px}
.dcol{position:relative}
.dcol .card{position:absolute;left:0;right:0;width:auto;height:60px}
.dflow{width:100%;height:540px}
.ddest{position:absolute;left:0;right:0;display:flex;align-items:center;gap:12px;padding:14px 18px;border-radius:30px;color:#fff!important;min-height:124px;text-align:left;box-shadow:var(--e2);transition:transform .4s var(--spring),border-radius .4s var(--spring)}
.ddest:hover{transform:scale(1.04);border-radius:44px}
.cells .net{background:var(--line)}
/* ---------- phone ---------- */
.ph{position:relative;width:390px;height:844px;overflow:hidden;display:flex;flex-direction:column;isolation:isolate;background:radial-gradient(420px 300px at 90% -4%,oklch(from var(--accent) calc(.84 - var(--dark) * .56) .1 calc(h + 55) / .6),transparent 70%),var(--bg)}
.sb{display:flex;justify-content:space-between;align-items:center;padding:14px 26px 4px;font-weight:760;font-size:14px;flex:none}
.ab{display:flex;align-items:center;gap:8px;padding:6px 16px 8px;flex:none}
.ab h1{font-size:30px;font-weight:800;font-stretch:76%;margin-right:auto;line-height:1}
.pc{flex:1;min-height:0;overflow:hidden;padding:4px 14px 14px;display:flex;flex-direction:column;gap:12px}
.pc>*{flex:none}
.ph .hero{border-radius:32px;padding:20px;grid-template-columns:1fr;min-height:0;gap:14px}
.ph .hero h2{font-size:28px}.ph .disp{font-size:76px}.ph .disp.m{font-size:44px}
.ph .bento{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}
.ph .tile{grid-column:span 2;border-radius:26px;padding:16px;gap:10px}
.ph .tile.half{grid-column:span 1}
.ph .glass{border-radius:22px;padding:14px}
.bn{flex:none;display:flex;justify-content:space-around;align-items:center;height:80px;padding:0 8px 8px;background:var(--glass);backdrop-filter:blur(22px) saturate(1.5);border-top:1px solid var(--line)}
.bn a{display:flex;flex-direction:column;align-items:center;gap:4px;font-size:11.5px;font-weight:700;color:var(--sub);text-decoration:none;min-width:60px;min-height:48px;justify-content:center}
.bn a span.pl{width:60px;height:32px;border-radius:16px;display:grid;place-items:center;transition:background .3s,width .4s var(--spring)}
.bn a.on{color:var(--text)}.bn a.on span.pl{background:var(--primary-c);color:var(--on-primary-c);animation:pillIn .6s var(--spring) both}
.ph .stagebar>span{display:none}.ph .stagebar .seg{width:100%;display:grid;min-height:44px}.ph .stagebar .seg button{padding:0 2px;font-size:11.5px;min-height:36px}
.glass .map .n1,.glass .map .n2{fill:#fff;stroke:rgb(255 255 255 / .5)}.glass .map text{fill:#fff}
.tile>.sl,.colx>.sl,.tile>.pw,.colx>.pw,.glass>.sl{flex:none}
.ring .gc{display:flex;flex-direction:column;align-items:center;line-height:1}.ring .gc small{font-size:12.5px;font-weight:700;opacity:.9;margin-top:4px}
.disp.xs{font-size:30px}
.ph .scrim{backdrop-filter:blur(2px);background:rgb(8 10 28 / .34)}
.ph .pipe{flex-wrap:nowrap}.ph .pipe .pn{width:36px;height:36px}.ph .pipe .pc{margin:0 4px;min-width:8px}.ph .pipe .ps{gap:0}
.pfab{position:absolute;right:18px;bottom:98px;z-index:4}

/* ---------- keyframes ---------- */
@keyframes rise{from{opacity:0;transform:translateY(34px) scale(.95)}}
@keyframes fade{from{opacity:0}}
@keyframes pop{from{opacity:0;transform:scale(.3)}}
@keyframes growX{from{transform:scaleX(0)}}
@keyframes growY{from{transform:scaleY(0)}}
@keyframes draw{from{stroke-dashoffset:1}}
@keyframes gauge{from{stroke-dasharray:0 100}}
@keyframes sweep{from{transform:translateX(-110%)}to{transform:translateX(110%)}}
@keyframes cnt{from{--v:0}}
@keyframes cdown{from{--v:var(--from)}to{--v:0}}
@keyframes spin{to{transform:rotate(360deg)}}
@keyframes spinang{to{--ang:360deg}}
@keyframes pulse{0%{box-shadow:0 0 0 0 color-mix(in oklab,currentColor 60%,transparent);opacity:1}70%{box-shadow:0 0 0 12px transparent;opacity:.75}100%{box-shadow:0 0 0 0 transparent;opacity:1}}
@keyframes blip{0%,100%{box-shadow:0 0 0 0 rgb(255 255 255 / .7);transform:scale(.7)}40%{box-shadow:0 0 0 14px rgb(255 255 255 / 0);transform:scale(1.2)}}
@keyframes redpulse{from{box-shadow:0 0 0 0 var(--bad)}to{box-shadow:0 0 0 30px transparent}}
@keyframes shake{0%,100%{transform:translateX(0)}15%{transform:translateX(-14px) rotate(-.6deg)}30%{transform:translateX(12px) rotate(.5deg)}45%{transform:translateX(-9px)}60%{transform:translateX(6px)}80%{transform:translateX(-3px)}}
@keyframes slideIn{from{opacity:0;transform:translateX(-40px)}}
@keyframes shim{to{background-position:-200% 0}}
@keyframes blink{50%{opacity:0}}
@keyframes waveX{to{transform:translateX(-40px)}}
@keyframes flow{from{offset-distance:0%}to{offset-distance:100%}}
@keyframes dash{to{background-position:28px 0}}
@keyframes breathe{50%{opacity:.6}}
@keyframes burst{0%{transform:translate(0,0) scale(.2);opacity:1}70%{opacity:1}100%{transform:translate(var(--tx),var(--ty)) scale(1) rotate(200deg);opacity:0}}
@keyframes morph{0%,100%{clip-path:${SH.cookie};transform:rotate(0)}33%{clip-path:${SH.clover};transform:rotate(60deg)}66%{clip-path:${SH.flower};transform:rotate(120deg)}}
@keyframes blob1{to{transform:translate(26%,34%) scale(1.25) rotate(40deg);border-radius:61% 39% 35% 65%/57% 62% 38% 43%}}
@keyframes blob2{to{transform:translate(-38%,-30%) scale(.85) rotate(-50deg);border-radius:36% 64% 58% 42%/41% 33% 67% 59%}}
@keyframes blob3{to{transform:translate(-60%,50%) scale(1.3) rotate(70deg);border-radius:55% 45% 33% 67%/63% 51% 49% 37%}}
@keyframes dockIn{from{opacity:0;transform:translateY(80px) scale(.9)}}
@keyframes dlg{from{opacity:0;transform:translateY(60px) scale(.86)}}
@keyframes sheetX{from{transform:translateX(100%)}}
@keyframes sheetY{from{transform:translateY(100%)}}
@keyframes toastIn{from{opacity:0;transform:translateX(120px) scale(.9)}}
@keyframes pillIn{from{width:20px;opacity:.3}}
.cnt{animation:cnt 1.6s var(--ease) both .25s}
.cdn{--v:var(--to);counter-reset:n var(--v);animation:cdown calc(var(--from) * 1s) linear both}
.cdn::after{content:counter(n)}

/* ---------- motion Tweak: standard removes the dramatic set, calm stills everything ---------- */
.std .flowbar i,.std .aurora i,.std .morph,.std .hot::before,.std .radar::before,.std .radar b,.std .map .pk,.std .ring .wv,.std .ring .wv2,.std .burst i,.std .cnt,.std .cdn,.std .ch .swp,.std .okmark .bg,.std .nomark::before,.std .empty .eshape,.std .modec.act .ms,.std .pipe .ps.now .pn,.std .dr{animation:none!important}
.std .burst,.std .ch .swp{display:none}
.calm,.calm *,.calm *::before,.calm *::after{animation:none!important;transition:none!important}
.calm .burst,.calm .ch .swp,.calm .map .pk{display:none}
@media (prefers-reduced-motion:reduce){.mx,.mx *,.mx *::before,.mx *::after{animation:none!important;transition:none!important}.mx .burst,.mx .ch .swp,.mx .map .pk{display:none}}
`;
